SELECT Станции2021.NUMB1120, Имена_ОЭС.nameoes, Имена_областей.NAME AS oblast, Станции2021.NAME AS stancia, Станции2021.NUST, Станции2021.EURT, [cena_Be]*1.202238 AS cena_topl_zatr_2023, [avg_gaz_c]*1.202238 AS cena_gaz_2023, IIf([Станции2021].[oes]<7,[avg_gaz_c]*1.452434488,[avg_gaz_c]*1.717260255) AS cena_gaz_2042, [avg_ugol]*1.202238 AS cena_ugol_2023, [Расчёт средней цены топлива].avg_gaz_c, [Расчёт средней цены топлива].avg_ugol, Затраты_топливо_2021.cena_e AS toplzatr_na_EOTP, Цена_энергии_2021.cena_e AS vsezatr_na_EOTP, Затраты_топливо_2021.cena_Be, IIf([форэм]=1,"опт","розн") AS Opt, Round([E]/[NUST]*1000,0) AS Hust, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Станции2021.OBOR
FROM (Имена_станций INNER JOIN ((((Станции2021 LEFT JOIN Затраты_топливо_2021 ON Станции2021.NUMB1120 = Затраты_топливо_2021.NUMB1120) LEFT JOIN [Расчёт средней цены топлива] ON Станции2021.NUMB1120 = [Расчёт средней цены топлива].NUMB1120) INNER JOIN Имена_областей ON Станции2021.OBL = Имена_областей.OBL) INNER JOIN Имена_ОЭС ON Станции2021.OES = Имена_ОЭС.oes) ON Имена_станций.NUMB = Станции2021.NUMB1120) LEFT JOIN Цена_энергии_2021 ON Станции2021.NUMB1120 = Цена_энергии_2021.NUMB1120
ORDER BY Станции2021.numb1;
